content:
此附加元件可讓您為 [Ars Nouveau](https://www.curseforge.com/minecraft/mc-mods/ars-nouveau) 模組創建合成配方。

注意：Modrinth 並未託管 Ars Nouveau 模組，因此要執行此模組，您必須從其他來源安裝它。

```js
ServerEvents.recipes(event => {
	event.recipes.ars_nouveau.enchanting_apparatus(
        [
            "minecraft:sand",
            "minecraft:sand",
            "minecraft:sand",
            "minecraft:sand",
        ], // 輸入物品
	    "minecraft:gunpowder", // 反應物
	    "minecraft:tnt", // 輸出
	    1000, // 源質消耗
	    // true // 保留反應物的 NBT，類似鍛造合成
	);

	event.recipes.ars_nouveau.enchantment(
        [
            "minecraft:sand",
            "minecraft:sand",
            "minecraft:sand",
            "minecraft:sand",
        ], // 輸入物品
        "minecraft:vanishing_curse", // 應用附魔
        1, // 附魔等級
        1000, // 源質消耗
    );

	event.recipes.ars_nouveau.crush(
        "minecraft:tnt", // 輸入方塊
        [{
            item: "minecraft:sand",
            chance: 1
        }] // 戰利品表
        // true // 是否將物品掉落於世界中？
    );

    /*
    // 這個配方確實有效，但合成必須是書卷中有效的魔符，
    // 因此這實際上只能用於替換某個魔符的配方
    event.recipes.ars_nouveau.glyph(
        "minecraft:tnt", // 輸出物品（魔符）
        [
            "minecraft:sand", 
            "minecraft:gunpowder",
        ], // 輸入物品
        3 // 經驗消耗
    );
    */

    // 可透過 `/ars-tome id` 存取，在此例中為 `/ars-tome kubejs:not_glow`
  	// 這是直接複製自 Ars Nouveau 基礎模組中的發光陷阱書卷
    event.recipes.ars_nouveau.caster_tome(
        "非發光陷阱", // 名稱,
        [
            "ars_nouveau:glyph_touch",
            "ars_nouveau:glyph_rune",
            "ars_nouveau:glyph_snare",
            "ars_nouveau:glyph_extend_time",
            "ars_nouveau:glyph_light"
        ], // 法術
        "不會困住目標，而是讓其他目標獲得發光效果。", // 描述
        16718260, // 顏色
        {
            "family": "ars_nouveau:default",
            "pitch": 1.0,
            "volume": 1.0,
        },
    ).id("kubejs:not_glow")

    event.recipes.ars_nouveau.imbuement(
        "minecraft:sand", // 輸入物品
        "minecraft:tnt", // 輸出
        1000, // 源質消耗
        [
            "minecraft:gunpowder" 
        ] // 基座物品 // 可選
    )
})
```
